A stack (pile) is Last-In, First-Out (LIFO), like a stack of plates. A queue (file) is First-In, First-Out (FIFO), like a line of people. Here's a simple C example demonstrating the difference:

```c
#include <stdio.h>

// Stack (Pile) example - LIFO
void stack_example() {
    printf("Pile (LIFO):\n");
    // Imagine pushing items onto a stack
    printf("1. Push item A\n");
    printf("2. Push item B\n");
    printf("3. Push item C\n");
    // Imagine popping items off the stack
    printf("4. Pop: C (last in)\n");
    printf("5. Pop: B\n");
    printf("6. Pop: A (first in)\n");
}

// Queue (File) example - FIFO
void queue_example() {
    printf("\nFile (FIFO):\n");
    // Imagine enqueuing items
    printf("1. Enqueue item X\n");
    printf("2. Enqueue item Y\n");
    printf("3. Enqueue item Z\n");
    // Imagine dequeuing items
    printf("4. Dequeue: X (first in)\n");
    printf("5. Dequeue: Y\n");
    printf("6. Dequeue: Z (last in)\n");
}

int main() {
    stack_example();
    queue_example();
    return 0;
}
```
This code illustrates the conceptual difference; actual stack and queue implementations in C would typically use arrays or linked lists.

Une pile (stack) est une structure de données LIFO (dernier entré, premier sorti), tandis qu'une file (queue) est FIFO (premier entré, premier sorti). Pour une pile, on utilise `push` pour ajouter et `pop` pour retirer. Pour une file, on utilise `enqueue` pour ajouter et `dequeue` pour retirer.

Voici un exemple simple en C pour illustrer ces concepts.

```c
#include <stdio.h>
#include <stdlib.h>

// Structure pour un élément de pile/file
typedef struct Node {
    int data;
    struct Node* next;
} Node;

// Pile (Stack)
Node* top = NULL;

void push(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = top;
    top = newNode;
    printf("%d pushed to stack\n", data);
}

int pop() {
    if (top == NULL) {
        printf("Stack underflow\n");
        return -1; // Indicate error
    }
    Node* temp = top;
    int poppedData = temp->data;
    top = top->next;
    free(temp);
    return poppedData;
}

// File (Queue)
Node* front = NULL;
Node* rear = NULL;

void enqueue(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    if (rear == NULL) {
        front = rear = newNode;
    } else {
        rear->next = newNode;
        rear = newNode;
    }
    printf("%d enqueued to queue\n", data);
}

int dequeue() {
    if (front == NULL) {
        printf("Queue underflow\n");
        return -1; // Indicate error
    }
    Node* temp = front;
    int dequeuedData = temp->data;
    front = front->next;
    if (front == NULL) {
        rear = NULL;
    }
    free(temp);
    return dequeuedData;
}

int main() {
    // Pile example
    printf("--- Stack Example ---\n");
    push(10);
    push(20);
    printf("%d popped from stack\n", pop());

    // Queue example
    printf("\n--- Queue Example ---\n");
    enqueue(100);
    enqueue(200);
    printf("%d dequeued from queue\n", dequeue());
    printf("%d dequeued from queue\n", dequeue());

    return 0;
}
```

